	private static void awaitIfPresent(Future<?> future) {
		if (future != null) {
			try {
				future.get(5, TimeUnit.SECONDS);
			} catch (ExecutionException | java.util.concurrent.TimeoutException ignored) {
				// Preserve the primary assertion or native failure while allowing released work to finish.
			} catch (InterruptedException interrupted) {
				Thread.currentThread().interrupt();
			}
		}
	}

	private static void closeIfPresent(SailSink sink) {
		if (sink != null) {
			try {
				sink.close();
			} catch (RuntimeException | Error ignored) {
				// Preserve the primary assertion or native failure while attempting remaining cleanup.
			}
		}
	}

	private static void assertCommittedState(SailRepository repository, Statement prefix, Statement trigger,
			Statement triggerCompanion, Statement suffix, Statement nextWriter) {
		try (RepositoryConnection reader = repository.getConnection()) {
			assertTrue(reader.hasStatement(prefix, false));
			assertTrue(reader.hasStatement(trigger, false));
			assertTrue(reader.hasStatement(triggerCompanion, false));
			assertTrue(reader.hasStatement(suffix, false));
			assertEquals(nextWriter == null ? 4 : 5, reader.size(),
					"the retained prefix, trigger batch, suffix, and recovery write must each publish exactly once");
			if (nextWriter != null) {
				assertTrue(reader.hasStatement(nextWriter, false));
			}
			assertEquals("urn:direct-continuation:owned:", reader.getNamespace("owned"));
			assertEquals("urn:direct-continuation:tail:", reader.getNamespace("tail"));
			assertNull(reader.getNamespace("rejected"));
			assertNull(reader.getNamespace("alias"));
			assertFalse(reader.hasStatement(statement("alias"), false),
					"an approved alias statement must never enter the suspended generation");
		}
	}

	private static void approve(SailSink sink, Statement statement) throws SailException {
		sink.approve(statement.getSubject(), statement.getPredicate(), statement.getObject(), statement.getContext());
	}

	private static Statement statement(String suffix) {
		Resource context = Values.iri("urn:direct-continuation:context");
		return VF.createStatement(Values.iri("urn:direct-continuation:" + suffix),
				Values.iri("urn:direct-continuation:predicate"), Values.literal(suffix), context);
	}

	private enum AliasMutation {
		APPROVE {
			@Override
			void apply(SailSink sink, Statement prefix, Statement alias) throws SailException {
				LmdbDirectContinuationOwnershipTest.approve(sink, alias);
			}
		},
		APPROVE_ALL {
			@Override
			void apply(SailSink sink, Statement prefix, Statement alias) {
				sink.approveAll(Set.of(alias), Set.of());
			}
		},
		DEPRECATE {
			@Override
			void apply(SailSink sink, Statement prefix, Statement alias) throws SailException {
				sink.deprecate(prefix);
			}
		},
		SET_NAMESPACE {
			@Override
			void apply(SailSink sink, Statement prefix, Statement alias) throws SailException {
				sink.setNamespace("rejected", "urn:direct-continuation:rejected:");
			}
		},
		REMOVE_NAMESPACE {
			@Override
			void apply(SailSink sink, Statement prefix, Statement alias) throws SailException {
				sink.removeNamespace("owned");
			}
		},
		CLEAR_NAMESPACES {
			@Override
			void apply(SailSink sink, Statement prefix, Statement alias) throws SailException {
				sink.clearNamespaces();
			}
		};

		abstract void apply(SailSink sink, Statement prefix, Statement alias) throws SailException;
	}

	private record AliasAttemptResult(Throwable mutationFailure, Throwable closeFailure, boolean closedWhileSuspended) {
	}

	private static final class FaultInjectingLmdbStore extends LmdbStore {
		private FaultyTripleStore triples;

		private FaultInjectingLmdbStore(File directory, LmdbStoreConfig config) {
			super(directory, config);
		}

		@Override
		LmdbSailStore createBackingStore(File directory, StoreProperties properties, LmdbStoreConfig config,
				boolean sketchEnabled) throws IOException, SailException {
			return new LmdbSailStore(directory, properties, config, false,
					(dir, props, cfg) -> new ValueStore(dir, props, cfg),
					(dir, props, cfg, values) -> triples = new FaultyTripleStore(dir, props, cfg, values));
		}
	}

	private static final class FaultyTripleStore extends TripleStore {
		private final AtomicInteger failNextContextIncrement = new AtomicInteger();
		private final AtomicReference<Thread> injectedFailureThread = new AtomicReference<>();

		private FaultyTripleStore(File directory, StoreProperties properties, LmdbStoreConfig config, ValueStore values)
				throws IOException {
			super(directory, properties, config, values);
		}

		@Override
		void incrementAlignedContext(MemoryStack stack, long context, int amount) throws IOException {
			super.incrementAlignedContext(stack, context, amount);
			if (failNextContextIncrement.get() > 0 && failNextContextIncrement.decrementAndGet() == 0) {
				injectedFailureThread.set(Thread.currentThread());
				throw new MapFullException();
			}
		}
	}
